import{_ as a,o,c as i,ag as l}from"./chunks/framework.x5zXLvit.js";const p=JSON.parse('{"title":"SAMOO 攻击优化总结","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/attack-optimization-summary.md","filePath":"documentation/attack-optimization-summary.md","lastUpdated":null}'),t={name:"documentation/attack-optimization-summary.md"};function d(c,e,r,n,u,h){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="samoo-攻击优化总结" tabindex="-1">SAMOO 攻击优化总结 <a class="header-anchor" href="#samoo-攻击优化总结" aria-label="Permalink to &quot;SAMOO 攻击优化总结&quot;">​</a></h1><p>本文档汇总了本轮在 <code>src/psorad</code> 主实现中的攻击算法与工程质量优化，便于代码审查、论文复现实验记录和后续迭代。</p><h2 id="_1-优化目标与背景" tabindex="-1">1. 优化目标与背景 <a class="header-anchor" href="#_1-优化目标与背景" aria-label="Permalink to &quot;1. 优化目标与背景&quot;">​</a></h2><p>在初始实现中，SAMOO 在 CIFAR10 上表现较好，但在 Imagenette / 224 分辨率任务上成功率偏低。主要症结是：</p><ul><li>预设超参数对小图更友好，对大图探索强度不足；</li><li>进化过程缺少后期收敛稳定机制；</li><li>查询预算控制与成功判定边界需要更稳健；</li><li>提交前质量门禁（ruff/mypy/pytest）未完全打通。</li></ul><p>本轮优化围绕上述问题，形成了“分辨率自适应 + 置信度增强 + 动态变异 + 工程质量闭环”的改进方案。</p><h2 id="_2-攻击算法层优化" tabindex="-1">2. 攻击算法层优化 <a class="header-anchor" href="#_2-攻击算法层优化" aria-label="Permalink to &quot;2. 攻击算法层优化&quot;">​</a></h2><h3 id="_2-1-分辨率自适应预设-替代数据集名硬编码" tabindex="-1">2.1 分辨率自适应预设（替代数据集名硬编码） <a class="header-anchor" href="#_2-1-分辨率自适应预设-替代数据集名硬编码" aria-label="Permalink to &quot;2.1 分辨率自适应预设（替代数据集名硬编码）&quot;">​</a></h3><p>新增分辨率档位策略，根据图像总像素自动选择预设参数（small / large），不依赖数据集名称。</p><ul><li>small（如 32x32）与 large（如 224x224）使用不同 <code>eps_ratio</code> / <code>query_budget</code> / <code>pop_size</code> / <code>p_size</code>；</li><li>对于和 Imagenette 同分辨率的 psoriasis 数据，可直接复用同一策略；</li><li>用户手动传参时，仍以显式参数优先。</li></ul><h3 id="_2-2-查询预算驱动的迭代推导" tabindex="-1">2.2 查询预算驱动的迭代推导 <a class="header-anchor" href="#_2-2-查询预算驱动的迭代推导" aria-label="Permalink to &quot;2.2 查询预算驱动的迭代推导&quot;">​</a></h3><ul><li>新增 <code>query_budget</code> 参数；</li><li>当未显式给 <code>iterations</code> 时，自动按 <code>ceil(query_budget / pop_size)</code> 推导迭代次数；</li><li>使“预算可控性”优先于固定代数。</li></ul><h3 id="_2-3-动态变异率退火-pm-pm-end" tabindex="-1">2.3 动态变异率退火（pm -&gt; pm_end） <a class="header-anchor" href="#_2-3-动态变异率退火-pm-pm-end" aria-label="Permalink to &quot;2.3 动态变异率退火（pm -&gt; pm_end）&quot;">​</a></h3><ul><li>新增 <code>pm_end</code>；</li><li>每轮变异率 <code>pm_current</code> 在攻击过程中线性退火；</li><li>前期高探索，后期稳收敛，降低大分辨率任务搜索抖动。</li></ul><h3 id="_2-4-高置信样本自适应增强" tabindex="-1">2.4 高置信样本自适应增强 <a class="header-anchor" href="#_2-4-高置信样本自适应增强" aria-label="Permalink to &quot;2.4 高置信样本自适应增强&quot;">​</a></h3><p>当样本 <code>true_class_conf</code> 极高且核心参数未手动指定时，自动增强搜索强度：</p><ul><li>提升 <code>eps</code>、<code>query_budget</code>、<code>pop_size</code>；</li><li>并同步重算 <code>iterations</code>；</li><li>典型触发阈值：<code>&gt;= 0.995</code> 与 <code>&gt;= 0.9999</code>。</li></ul><p>该策略用于处理“高置信难攻样本”，已在 Imagenette 样例上验证有效。</p><h3 id="_2-5-查询预算边界成功判定修复" tabindex="-1">2.5 查询预算边界成功判定修复 <a class="header-anchor" href="#_2-5-查询预算边界成功判定修复" aria-label="Permalink to &quot;2.5 查询预算边界成功判定修复&quot;">​</a></h3><p>修复了一个关键边界问题：</p><ul><li>原逻辑在达到 <code>query_budget</code> 时会直接结束循环；</li><li>新逻辑会先检查当前种群是否已包含可行对抗解，再决定失败退出；</li><li>避免“最后一批查询已成功但被误判失败”。</li></ul><h2 id="_3-cli-与文档可用性优化" tabindex="-1">3. CLI 与文档可用性优化 <a class="header-anchor" href="#_3-cli-与文档可用性优化" aria-label="Permalink to &quot;3. CLI 与文档可用性优化&quot;">​</a></h2><h3 id="_3-1-attack-命令参数升级" tabindex="-1">3.1 attack 命令参数升级 <a class="header-anchor" href="#_3-1-attack-命令参数升级" aria-label="Permalink to &quot;3.1 attack 命令参数升级&quot;">​</a></h3><p><code>attack</code> 子命令新增/调整如下：</p><ul><li>新增：<code>--query-budget</code>、<code>--pm-end</code>；</li><li>改为可选覆盖：<code>--iterations</code>、<code>--pc</code>、<code>--pm</code>、<code>--pop-size</code>、<code>--zero-probability</code>、<code>--p-size</code>、<code>--tournament-size</code>；</li><li>不传时使用分辨率预设，传参时覆盖预设。</li></ul><h3 id="_3-2-日志可观测性增强" tabindex="-1">3.2 日志可观测性增强 <a class="header-anchor" href="#_3-2-日志可观测性增强" aria-label="Permalink to &quot;3.2 日志可观测性增强&quot;">​</a></h3><p>攻击日志新增关键字段：</p><ul><li>分辨率档位、是否触发置信度增强及触发原因；</li><li><code>query_budget</code>、<code>pm_end</code>、<code>pm_current</code>；</li><li>达到预算提前停止事件。</li></ul><p>这使失败分析与参数复现实验更直接。</p><h2 id="_4-工程质量优化-提交前门禁" tabindex="-1">4. 工程质量优化（提交前门禁） <a class="header-anchor" href="#_4-工程质量优化-提交前门禁" aria-label="Permalink to &quot;4. 工程质量优化（提交前门禁）&quot;">​</a></h2><h3 id="_4-1-静态与测试门禁打通" tabindex="-1">4.1 静态与测试门禁打通 <a class="header-anchor" href="#_4-1-静态与测试门禁打通" aria-label="Permalink to &quot;4.1 静态与测试门禁打通&quot;">​</a></h3><p>已按提交前流程执行并通过：</p><ul><li><code>ruff check .</code></li><li><code>mypy src</code></li><li><code>pytest</code></li></ul><h3 id="_4-2-质量修复项" tabindex="-1">4.2 质量修复项 <a class="header-anchor" href="#_4-2-质量修复项" aria-label="Permalink to &quot;4.2 质量修复项&quot;">​</a></h3><ul><li>修复 <code>mypy</code> 的 <code>no-any-return</code> / <code>union-attr</code> / <code>unused-ignore</code> 等问题；</li><li>新增最小 smoke 测试，避免 <code>pytest</code> 因“无测试”返回 exit code 5。</li></ul><h2 id="_5-结果与影响" tabindex="-1">5. 结果与影响 <a class="header-anchor" href="#_5-结果与影响" aria-label="Permalink to &quot;5. 结果与影响&quot;">​</a></h2><p>在高置信 Imagenette 样例中，策略触发后可见：</p><ul><li><code>applied=True, reason=very_high_confidence</code>；</li><li>攻击预算与扰动规模自动增强；</li><li>攻击成功率显著提升（示例中由失败变为成功）。</li></ul><h2 id="_6-后续建议" tabindex="-1">6. 后续建议 <a class="header-anchor" href="#_6-后续建议" aria-label="Permalink to &quot;6. 后续建议&quot;">​</a></h2><p>可继续迭代以下方向：</p><ul><li>value-only mutation（后期仅调扰动值）；</li><li>批量评测脚本（ASR vs Query 曲线）；</li><li>将预算边界与参数解析加入单元测试矩阵。</li></ul>',41)])])}const _=a(t,[["render",d]]);export{p as __pageData,_ as default};
